// Scroll to very bottom of the page
window.scrollTo(0, document.body.scrollHeight);
// Then check for any h2 headings or panel titles that are visible
Array.from(document.querySelectorAll('h2, section[aria-label]')).map(el => el.textContent || el.getAttribute('aria-label'))

// Look for panel title input
let inputs = document.querySelectorAll('input');
for (let inp of inputs) {
  let parent = inp.closest('[class*="panel"]') || inp.closest('section') || inp.parentElement;
  if (parent) {
    let label = parent.querySelector('label') || parent.previousElementSibling;
    if (label && (label.textContent.includes('Title') || label.textContent.includes('Panel'))) {
      console.log('FOUND:', {id: inp.id, placeholder: inp.placeholder, label: label.textContent, parentTag: parent.tagName, parentClass: parent.className});
    }
  }
}
// Also check for text-like inputs
Array.from(document.querySelectorAll('[class*="title"] input, [class*="Title"] input, [class*="panel"] input')).map(el => ({id: el.id, placeholder: el.placeholder, value: el.value, parentClass: el.closest('[class]')?.className}))

// Find Panel options heading, then look for the title field
let headings = document.querySelectorAll('h5, h6, [class*="heading"]');
let found = [];
for (let h of headings) {
  if (h.textContent.includes('Panel options')) {
    let section = h.closest('section') || h.parentElement;
    found.push(section.innerHTML.substring(0, 1000));
  }
}
found

